// =========================================================================
// Orbit Academy — courses.js
// 10 course tracks, 10–12 chapters each (beginner → intermediate → pro)
// Achievement post logic at the bottom — call createAchievementPost() on
// course completion from your academy UI.
// =========================================================================

import { db, auth } from "./app.js";
import {
  addDoc, collection, serverTimestamp, doc, setDoc, getDoc, updateDoc, arrayUnion,
} from "https://www.gstatic.com/firebasejs/10.13.2/firebase-firestore.js";

// =========================================================================
// ACHIEVEMENT POST — call this when a user finishes the last chapter
// =========================================================================
export async function createAchievementPost(courseId, courseTitle, courseEmoji) {
  const user = auth.currentUser;
  if (!user) return;

  const userSnap = await getDoc(doc(db, "users", user.uid));
  if (!userSnap.exists()) return;
  const profile = userSnap.data();

  const shareText = `🎓 Just completed the ${courseTitle} course on Orbit Academy! ${courseEmoji}\n\nFrom zero to pro — one chapter at a time. 🚀 #OrbitAcademy #${courseId.replace(/-/g, "")}`;

  // 1. Create a public feed post
  await addDoc(collection(db, "posts"), {
    uid:          user.uid,
    username:     profile.username,
    name:         profile.name,
    photoURL:     profile.photoURL || null,
    type:         "achievement",
    text:         shareText,
    courseId,
    courseTitle,
    courseEmoji,
    likes:        [],
    comments:     0,
    shares:       0,
    verified:     profile.verified || false,
    createdAt:    serverTimestamp(),
  });

  // 2. Record the achievement on the user's profile
  await updateDoc(doc(db, "users", user.uid), {
    achievements: arrayUnion({
      courseId,
      courseTitle,
      courseEmoji,
      earnedAt: new Date().toISOString(),
    }),
  });

  // 3. Write a dedicated achievement doc (for badges / profile tab)
  await setDoc(
    doc(db, "users", user.uid, "achievements", courseId),
    { courseId, courseTitle, courseEmoji, earnedAt: serverTimestamp() },
    { merge: true }
  );
}

// =========================================================================
// COURSE HELPERS — used by features.js
// =========================================================================

/** Return a course object by id, or undefined if not found. */
export function getCourse(courseId) {
  return COURSES.find((c) => c.id === courseId);
}

/**
 * Return a chapter object, or undefined if not found.
 * @param {string} courseId
 * @param {string} chapterId
 */
export function getChapter(courseId, chapterId) {
  const course = getCourse(courseId);
  if (!course) return undefined;
  return course.chapters.find((ch) => ch.id === chapterId);
}

/**
 * Return the chapter that comes after chapterId in the same course,
 * or null if chapterId is the last chapter.
 * @param {string} courseId
 * @param {string} chapterId
 */
export function getNextChapter(courseId, chapterId) {
  const course = getCourse(courseId);
  if (!course) return null;
  const idx = course.chapters.findIndex((ch) => ch.id === chapterId);
  if (idx === -1 || idx === course.chapters.length - 1) return null;
  return course.chapters[idx + 1];
}

